QUERIES = [
 ("SELECT - барлық бағандар", "SELECT * FROM Users;", "Users кестесіндегі барлық бағандар мен жазбалар шығады."),
 ("SELECT - белгілі бағандар", "SELECT full_name, email, city FROM Users;", "Тек аты-жөні, поштасы және қаласы көрсетіледі."),
 ("DISTINCT", "SELECT DISTINCT city FROM Users;", "Пайдаланушылар қалалары қайталанусыз шығады."),
 ("WHERE", "SELECT * FROM Vacancies WHERE city = 'Астана';", "Астана қаласындағы вакансиялар."),
 ("WHERE + AND", "SELECT * FROM Vacancies WHERE salary > 400000 AND experience_years >= 1;", "Жалақысы 400 000 теңгеден жоғары және кемінде 1 жыл тәжірибе талап ететін вакансиялар."),
 ("WHERE + OR", "SELECT * FROM Vacancies WHERE city = 'Астана' OR city = 'Алматы';", "Астана немесе Алматыдағы вакансиялар."),
 ("IN", "SELECT * FROM Skills WHERE category IN ('Бағдарламалау', 'Жасанды интеллект');", "Санаты берілген мәндердің біреуіне тең дағдылар."),
 ("BETWEEN", "SELECT * FROM Vacancies WHERE salary BETWEEN 300000 AND 500000;", "Жалақысы 300 000 - 500 000 аралығындағы вакансиялар (шекаралар қосылады)."),
 ("LIKE", "SELECT * FROM Vacancies WHERE title LIKE '%Developer%';", "Атауында Developer сөзі бар вакансиялар."),
 ("ORDER BY", "SELECT title, salary FROM Vacancies ORDER BY salary DESC;", "Вакансиялар жалақы бойынша кему ретімен сұрыпталады."),
 ("LIMIT", "SELECT title, salary FROM Vacancies ORDER BY salary DESC LIMIT 3;", "Жалақысы ең жоғары үш вакансия."),
 ("COUNT, MIN, MAX", "SELECT COUNT(*) AS total, MIN(salary) AS min_salary, MAX(salary) AS max_salary FROM Vacancies;", "Вакансия саны, ең төмен және ең жоғары жалақы."),
 ("JOIN", "SELECT u.full_name, v.title, a.application_date, a.status\nFROM Applications a\nJOIN Users u ON a.user_id = u.user_id\nJOIN Vacancies v ON a.vacancy_id = v.vacancy_id\nWHERE a.status = 'Қаралуда';", "Өтінімдер, пайдаланушылар және вакансиялар біріктіріледі; тек «Қаралуда» мәртебесі."),
 ("GROUP BY", "SELECT city, COUNT(*) AS vacancy_count FROM Vacancies GROUP BY city;", "Әр қаладағы вакансиялар саны."),
 ("GROUP BY + SUM", "SELECT city, SUM(salary) AS total_salary FROM Vacancies GROUP BY city;", "Қалалар бойынша вакансиялардағы жалақы мөлшерлерінің қосындысы."),
 ("GROUP BY + LEFT JOIN", "SELECT c.company_name, COUNT(v.vacancy_id) AS vacancy_count\nFROM Companies c\nLEFT JOIN Vacancies v ON c.company_id = v.company_id\nGROUP BY c.company_name;", "Әр компаниядағы вакансия саны; вакансиясы жоқ компания үшін 0."),
 ("UNION", "SELECT city FROM Users UNION SELECT city FROM Companies;", "Пайдаланушылар мен компаниялар қалалары, қайталанбайды."),
 ("UNION ALL", "SELECT city FROM Users UNION ALL SELECT city FROM Companies;", "Қайталанатын жолдар сақталады."),
]
